<script>
$(function(){var optionUrl=@json(route('asset.maintenance.options')),attachmentUrl=@json(route('asset.maintenance.attachments.index',$maintenance)),text=$.fn.dataTable.render.text();function loadAttachments(){$.getJSON(attachmentUrl).done(function(response){var rows=response.data||[];$('#maintenance-attachments').html(rows.length?rows.map(function(row){return '<div class="col-12 col-md-6"><div class="border rounded p-2 d-flex justify-content-between gap-2"><div><div class="fw-semibold">'+text.display(row.original_name)+'</div><div class="small text-secondary">'+text.display(row.uploaded_by)+' · '+text.display(row.uploaded_at)+'</div></div><div><a class="btn btn-sm btn-outline-dark" href="'+text.display(row.download_url)+'">ดาวน์โหลด</a>' +(row.delete_url?' <button class="btn btn-sm btn-outline-danger js-delete-maintenance-attachment" data-url="'+text.display(row.delete_url)+'">ลบ</button>':'')+'</div></div></div>';}).join(''):'<p class="text-secondary mb-0">ยังไม่มีหลักฐานแนบ</p>');}).fail(function(){$('#maintenance-attachments').html('<p class="text-danger mb-0">โหลดหลักฐานไม่สำเร็จ</p>');});}loadAttachments();window.erpAjaxForm({form:'#maintenance-attachment-form',reload:false});$(document).on('click','.js-delete-maintenance-attachment',function(){var $button=$(this);Swal.fire({icon:'warning',text:'ยืนยันลบหลักฐานนี้หรือไม่?',showCancelButton:true}).then(function(result){if(!result.isConfirmed)return;$button.prop('disabled',true);$.ajax({url:$button.data('url'),method:'DELETE',headers:{'X-CSRF-TOKEN':$('meta[name=csrf-token]').attr('content')}}).done(function(response){Swal.fire({icon:'success',title:response.msg});loadAttachments();}).fail(window.erpAjaxError).always(function(){$button.prop('disabled',false);});});});$(document).ajaxComplete(function(e,x,s){if(s.url===@json(route('asset.maintenance.attachments.store',$maintenance))&&x.status<300)loadAttachments();});window.erpInitSelect2($('.js-assignee'),{dropdownParent:$('#assign-modal'),placeholder:'ค้นหาผู้รับผิดชอบ',minimumInputLength:0,ajax:{url:optionUrl,delay:250,data:function(params){return{type:'assignee',q:params.term||'',page:params.page||1};},processResults:function(data){return data;}}});$('.js-maintenance-form').on('submit',function(event){event.preventDefault();var $form=$(this),$button=$form.find('[type=submit]');$button.prop('disabled',true);$.post($form.attr('action'),$form.serialize()).done(function(response){Swal.fire({icon:'success',title:response.msg}).then(function(){window.location=response.redirect;});}).fail(window.erpAjaxError).always(function(){$button.prop('disabled',false);});});$('.js-simple-action').on('click',function(){var $button=$(this),data={_token:@json(csrf_token())};Swal.fire({icon:'question',title:$button.data('title'),input:$button.data('date')?'date':undefined,inputValue:$button.data('date')?@json(today()->toDateString()):undefined,showCancelButton:true,confirmButtonText:'ยืนยัน',preConfirm:function(value){if($button.data('date')&&!value)Swal.showValidationMessage('กรุณาเลือกวันที่เริ่มซ่อม');}}).then(function(result){if(!result.isConfirmed)return;if($button.data('date'))data.started_date=result.value;$button.prop('disabled',true);$.post($button.data('url'),data).done(function(response){Swal.fire({icon:'success',title:response.msg}).then(function(){window.location=response.redirect;});}).fail(window.erpAjaxError).always(function(){$button.prop('disabled',false);});});});$('.js-cancel').on('click',function(){var $button=$(this);Swal.fire({icon:'warning',title:'ยกเลิกใบแจ้งซ่อม?',input:'textarea',inputLabel:'เหตุผล',showCancelButton:true,confirmButtonText:'ยืนยันยกเลิก',preConfirm:function(value){if(!value||value.trim().length<10)Swal.showValidationMessage('กรุณาระบุเหตุผลอย่างน้อย 10 ตัวอักษร');}}).then(function(result){if(!result.isConfirmed)return;$button.prop('disabled',true);$.post($button.data('url'),{_token:@json(csrf_token()),cancellation_reason:result.value}).done(function(response){Swal.fire({icon:'success',title:response.msg}).then(function(){window.location=response.redirect;});}).fail(window.erpAjaxError).always(function(){$button.prop('disabled',false);});});});});
</script>
